result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tplx/expressions.py", "content": """"Safe expression evaluation for {{ }} outputs, {% if %} and {% for %}.

Expressions are parsed with Python's own grammar but restricted to a small,
side-effect-free whitelist: literals, names, attribute access, subscripting,
lists/tuples/dicts, arithmetic, comparisons and boolean logic. Function calls
and everything else are rejected.
"""

import ast
import operator

from .errors import TemplateError

_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}

_CMPOPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}

_ALLOWED = (
    ast.Expression,
    ast.Constant,
    ast.Name,
    ast.Load,
    ast.List,
    ast.Tuple,
    ast.Dict,
    ast.Attribute,
    ast.Subscript,
    ast.Slice,
    ast.UnaryOp,
    ast.Not,
    ast.USub,
    ast.UAdd,
    ast.BinOp,
    ast.BoolOp,
    ast.And,
    ast.Or,
    ast.Compare,
) + tuple(_BINOPS) + tuple(_CMPOPS)

_ALLOWED = frozenset(_ALLOWED)


class _UndefinedName(Exception):
    """Internal signal carrying the name that was not found."""

    def __init__(self, name):
        super().__init__(name)
        self.name = name


def _eval(node, context):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        try:
            return context[node.id]
        except KeyError:
            raise _UndefinedName(node.id) from None
    if isinstance(node, ast.List):
        return [_eval(e, context) for e in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_eval(e, context) for e in node.elts)
    if isinstance(node, ast.Dict):
        return {
            (_eval(k, context) if k is not None else None): _eval(v, context)
            for k, v in zip(node.keys, node.values)
        }
    if isinstance(node, ast.Attribute):
        return getattr(_eval(node.value, context), node.attr)
    if isinstance(node, ast.Subscript):
        obj = _eval(node.value, context)
        key = _eval(node.slice, context)
        return obj[key]
    if isinstance(node, ast.Slice):
        lower = _eval(node.lower, context) if node.lower else None
        upper = _eval(node.upper, context) if node.upper else None
        step = _eval(node.step, context) if node.step else None
        return slice(lower, upper, step)
    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand, context)
        if isinstance(node.op, ast.Not):
            return not operand
        if isinstance(node.op, ast.USub):
            return -operand
        if isinstance(node.op, ast.UAdd):
            return +operand
    if isinstance(node, ast.BinOp):
        left = _eval(node.left, context)
        right = _eval(node.right, context)
        return _BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for value_node in node.values:
                result = _eval(value_node, context)
                if not result:
                    return result
            return result
        result = False
        for value_node in node.values:
            result = _eval(value_node, context)
            if result:
                return result
        return result
    if isinstance(node, ast.Compare):
        left = _eval(node.left, context)
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval(comparator, context)
            if not _CMPOPS[type(op)](left, right):
                return False
            left = right
        return True
    raise TemplateError(f"unsupported expression construct: {type(node).__name__}")


def evaluate(expression, context, line=None, name="<template>"):
    """Evaluate *expression* (a string) against *context*.

    Raises TemplateError naming the variable and line number for undefined
    variables, and for disallowed or invalid expressions.
    """
    try:
        tree = ast.parse(expression.strip(), mode="eval")
    except SyntaxError as exc:
        raise TemplateError(
            f"invalid expression {expression!r}", line=line, template_name=name
        ) from exc

    for node in ast.walk(tree):
        if not isinstance(node, _ALLOWED):
            raise TemplateError(
                f"disallowed construct in expression {expression!r}: "
                f"{type(node).__name__}",
                line=line,
                template_name=name,
            )

    try:
        return _eval(tree.body, context)
    except _UndefinedName as exc:
        raise TemplateError(
            f"undefined variable '{exc.name}'", line=line, template_name=name
        ) from None
    except ZeroDivisionError as exc:
        raise TemplateError(
            f"division by zero in expression {expression!r}",
            line=line,
            template_name=name,
        ) from exc
    except TemplateError:
        raise
    except Exception as exc:
        raise TemplateError(
            f"error evaluating {expression!r}: {exc}",
            line=line,
            template_name=name,
        ) from exc
