import re

from .errors import TemplateSyntaxError
from .tokenizer import TOKEN_TAG, TOKEN_TEXT, TOKEN_VAR, tokenize

_FOR_RE = re.compile(
    r"^for\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s+in\s+(.+)$", re.DOTALL
)
_IF_RE = re.compile(r"^if\s+(.+)$", re.DOTALL)
_ELIF_RE = re.compile(r"^elif\s+(.+)$", re.DOTALL)
_STRING_ARG_RE = re.compile(r'^(include|extends)\s+(?:"([^"]*)"|\'([^\']*)\')\s*$')
_BLOCK_RE = re.compile(r"^block\s+([A-Za-z_]\w*)\s*$")

# Tags that terminate an enclosing block construct.
_TERMINATORS = frozenset({"endfor", "endif", "endblock", "else", "elif"})


class Node:
    __slots__ = ()


class TextNode(Node):
    __slots__ = ("text",)

    def __init__(self, text):
        self.text = text


class ExprNode(Node):
    """{{ expression }}"""

    __slots__ = ("expression", "line")

    def __init__(self, expression, line):
        self.expression = expression
        self.line = line


class ForNode(Node):
    __slots__ = ("targets", "iter_expr", "body", "line")

    def __init__(self, targets, iter_expr, body, line):
        self.targets = targets  # list of 1 or more loop variable names
        self.iter_expr = iter_expr
        self.body = body
        self.line = line


class IfNode(Node):
    __slots__ = ("branches", "orelse", "line")

    def __init__(self, branches, orelse, line):
        self.branches = branches  # list of (condition_expr, body_nodes)
        self.orelse = orelse      # list of nodes (possibly empty)
        self.line = line


class IncludeNode(Node):
    __slots__ = ("name", "line")

    def __init__(self, name, line):
        self.name = name
        self.line = line


class ExtendsNode(Node):
    __slots__ = ("name", "line")

    def __init__(self, name, line):
        self.name = name
        self.line = line


class BlockNode(Node):
    __slots__ = ("name", "body", "line")

    def __init__(self, name, body, line):
        self.name = name
        self.body = body
        self.line = line


def parse(source, name="<template>"):
    """Parse template *source* into a list of top-level nodes."""
    return _Parser(tokenize(source, name), name).parse()


class _Parser:
    def __init__(self, tokens, name):
        self.tokens = tokens
        self.pos = 0
        self.name = name

    # -- helpers ----------------------------------------------------------

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _error(self, message, line=None):
        raise TemplateSyntaxError(message, line=line, template_name=self.name)

    def _last_line(self):
        return self.tokens[-1].line if self.tokens else 1

    # -- grammar ----------------------------------------------------------

    def parse(self):
        nodes, stop = self._parse_block(())
        if stop is not None:
            word, _, line = stop
            self._error(f"unexpected {{% {word} %}}: no open block to close", line)
        return nodes

    def _parse_block(self, terminators):
        """Parse nodes until EOF or a terminator tag.

        Returns (nodes, stop) where stop is None at EOF, otherwise a tuple
        (tag_word, tag_rest, line). The terminator token is consumed.
        """
        nodes = []
        while True:
            token = self._peek()
            if token is None:
                if terminators:
                    expected = " or ".join(sorted(f"{{% {t} %}}" for t in terminators))
                    self._error(
                        f"unclosed block: expected {expected} before end of template",
                        line=self._last_line(),
                    )
                return nodes, None
            self.pos += 1

            if token.kind == TOKEN_TEXT:
                nodes.append(TextNode(token.value))
            elif token.kind == TOKEN_VAR:
                nodes.append(ExprNode(token.value, token.line))
            else:  # TOKEN_TAG
                parts = token.value.split(None, 1)
                word = parts[0]
                rest = parts[1].strip() if len(parts) > 1 else ""

                if word in terminators:
                    return nodes, (word, rest, token.line)

                if word == "for":
                    nodes.append(self._parse_for(token, rest))
                elif word == "if":
                    nodes.append(self._parse_if(token, rest))
                elif word in ("include", "extends"):
                    match = _STRING_ARG_RE.match(token.value)
                    if not match:
                        self._error(
                            f'malformed {{% {word} %}} tag: expected a quoted '
                            f'template name, e.g. {{% {word} "file.html" %}}',
                            line=token.line,
                        )
                    template_name = match.group(2) or match.group(3)
                    cls = IncludeNode if word == "include" else ExtendsNode
                    nodes.append(cls(template_name, token.line))
                elif word == "block":
                    match = _BLOCK_RE.match(token.value)
                    if not match:
                        self._error(
                            f"malformed {{% block %}} tag: expected a name, "
                            f'e.g. {{% block "content" %}}'.replace('"content"', "content"),
                            line=token.line,
                        )
                    body, _ = self._parse_block(("endblock",))
                    nodes.append(BlockNode(match.group(1), body, token.line))
                elif word in _TERMINATORS:
                    self._error(
                        f"unexpected {{% {word} %}}: no matching open block",
                        line=token.line,
                    )
                else:
                    self._error(f"unknown tag {word!r}", line=token.line)

    def _parse_for(self, token, rest):
        match = _FOR_RE.match(token.value)
        if not match:
            self._error(
                f"malformed for tag: expected {{% for x in expr %}}, got "
                f"{{% {token.value} %}}",
                line=token.line,
            )
        targets = [part.strip() for part in match.group(1).split(",")]
        body, _ = self._parse_block(("endfor",))
        return ForNode(targets, match.group(2).strip(), body, token.line)

    def _parse_if(self, token, rest):
        match = _IF_RE.match(token.value)
        if not match:
            self._error(
                f"malformed if tag: expected {{% if cond %}}, got {{% {token.value} %}}",
                line=token.line,
            )
        branches = []
        orelse = []
        condition = match.group(1).strip()
        while True:
            body, stop = self._parse_block(("elif", "else", "endif"))
            branches.append((condition, body))
            word, tag_rest, _line = stop
            if word == "elif":
                condition = tag_rest
                continue
            if word == "else":
                orelse, _ = self._parse_block(("endif",))
            break
        return IfNode(branches, orelse, token.line)
