result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tplx/renderer.py", "content": """"Renderer: walks the node tree and produces output.

Handles variable substitution, loops, conditionals, includes (resolved
relative to the template's directory) and single-level template inheritance
via {% extends %} + {% block %}.
"""

from pathlib import Path

from . import expressions
from .errors import TemplateError
from .parser import (
    BlockNode,
    ExprNode,
    ExtendsNode,
    ForNode,
    IfNode,
    IncludeNode,
    TextNode,
    parse,
)


def render_string(source, context=None, base_dir=None, name="<template>"):
    """Render a template given as a string.

    *base_dir* is the directory used to resolve {% include %} and
    {% extends %}; if omitted, those tags raise TemplateError.
    """
    nodes = parse(source, name)
    return Renderer(base_dir=base_dir, name=name).render(nodes, context or {})


def render_file(path, context=None):
    """Render the template file at *path*.

    Includes and extends are resolved relative to the file's directory.
    """
    path = Path(path)
    try:
        source = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise TemplateError(f"cannot read template {str(path)!r}: {exc}") from exc
    return render_string(source, context, base_dir=path.parent, name=path.name)


class Renderer:
    def __init__(self, base_dir=None, name="<template>"):
        self.base_dir = Path(base_dir) if base_dir is not None else None
        self.name = name

    # -- public API --------------------------------------------------------

    def render(self, nodes, context):
        """Render a full template (top-level entry point)."""
        extends = None
        for node in nodes:
            if isinstance(node, ExtendsNode):
                extends = node
                break

        if extends is None:
            return self._render_nodes(nodes, dict(context), {})

        # Template inheritance: collect the child's blocks and render the
        # parent, letting parent-side blocks pick up the overrides.
        overrides = {}
        _collect_blocks(nodes, overrides)
        parent_nodes = self._load(extends.name, extends.line, "extends")
        parent_renderer = Renderer(self.base_dir, extends.name)
        return parent_renderer._render_nodes(parent_nodes, dict(context), overrides)

    # -- internals ---------------------------------------------------------

    def _load(self, template_name, line, kind):
        if self.base_dir is None:
            raise TemplateError(
                f'{{% {kind} "{template_name}" %}} requires a template directory',
                line=line,
                template_name=self.name,
            )
        path = self.base_dir / template_name
        if not path.is_file():
            raise TemplateError(
                f'{kind} target "{template_name}" not found in {self.base_dir}',
                line=line,
                template_name=self.name,
            )
        return path.read_text(encoding="utf-8")

    def _render_nodes(self, nodes, context, overrides, out=None):
        out = [] if out is None else out
        for node in nodes:
            self._render_node(node, context, overrides, out)
        return "".join(out)

    def _render_node(self, node, context, overrides, out):
        if isinstance(node, TextNode):
            out.append(node.text)

        elif isinstance(node, ExprNode):
            value = expressions.evaluate(
                node.expression, context, node.line, self.name
            )
            out.append(_to_str(value))

        elif isinstance(node, ForNode):
            iterable = expressions.evaluate(
                node.iter_expr, context, node.line, self.name
            )
            try:
                iterator = iter(iterable)
            except TypeError as exc:
                raise TemplateError(
                    f"cannot iterate over {node.iter_expr!r}: "
                    f"{type(iterable).__name__} is not iterable",
                    line=node.line,
                    template_name=self.name,
                ) from exc
            for item in iterator:
                frame = dict(context)
                if len(node.targets) == 1:
                    frame[node.targets[0]] = item
                else:
                    try:
                        values = tuple(item)
                    except TypeError as exc:
                        raise TemplateError(
                            f"cannot unpack loop item in {{% for ... %}}",
                            line=node.line,
                            template_name=self.name,
                        ) from exc
                    if len(values) != len(node.targets):
                        raise TemplateError(
                            f"cannot unpack {len(values)} value(s) into "
                            f"{len(node.targets)} loop variable(s)",
                            line=node.line,
                            template_name=self.name,
                        )
                    for name, value in zip(node.targets, values):
                        frame[name] = value
                self._render_nodes(node.body, frame, overrides, out)

        elif isinstance(node, IfNode):
            for condition, body in node.branches:
                if expressions.evaluate(condition, context, node.line, self.name):
                    self._render_nodes(body, context, overrides, out)
                    break
            else:
                self._render_nodes(node.orelse, context, overrides, out)

        elif isinstance(node, IncludeNode):
            source = self._load(node.name, node.line, "include")
            included = parse(source, node.name)
            included_renderer = Renderer(self.base_dir, node.name)
            out.append(included_renderer.render(included, context))

        elif isinstance(node, BlockNode):
            body = overrides.get(node.name, node.body)
            self._render_nodes(body, context, overrides, out)

        elif isinstance(node, ExtendsNode):
            # Handled once by render(); ignore stray occurrences deeper in
            # the tree.
            pass

        else:  # pragma: no cover - all node types are handled above
            raise TemplateError(f"unknown node type {type(node).__name__}")


def _collect_blocks(nodes, overrides):
    """Recursively gather BlockNodes into *overrides* (first one wins)."""
    for node in nodes:
        if isinstance(node, BlockNode):
            overrides.setdefault(node.name, node.body)
            _collect_blocks(node.body, overrides)
        elif isinstance(node, ForNode):
            _collect_blocks(node.body, overrides)
        elif isinstance(node, IfNode):
            for _, body in node.branches:
                _collect_blocks(body, overrides)
            _collect_blocks(node.orelse, overrides)


def _to_str(value):
    if value is None:
        return ""
    return str(value)
